(()=>{'use strict';
 const D=window.AgeTeachingData,$=id=>document.getElementById(id),params=new URLSearchParams(location.search);
 const mode=['match','show','name'].includes(params.get('mode'))?params.get('mode'):'match',method=params.get('method')==='immediate'?'immediate':'wait';
 const isShort=params.get('concept')==='old',concept=isShort?'old':'young';if(isShort)document.title='Yaşlı kavramı · Dijital Erken Eğitim';
 const titles={match:'Genç kavramı · eşle',show:'Genç kavramı · göster',name:'Genç kavramı · söyle'};
 if(isShort)for(const key of Object.keys(titles))titles[key]=titles[key].replace('Genç','Yaşlı');document.querySelector('.kicker').textContent=isShort?'Yaşlı kavramı':'Genç kavramı';$('sourceNote').textContent=isShort?'Alttaki yaşlı kişiyi üstteki yaşlı kişiyle eşle. Sürükleyebilir veya önce karta, sonra eşine dokunabilirsin.':$('sourceNote').textContent;$('source').setAttribute('aria-label',isShort?'Eşlenecek yaşlı kişi':'Eşlenecek genç kişi');
 document.body.dataset.mode=mode;
 let selectedColor=isShort?'old':'young',level=1,blockIndex=0,course=[],index=0,token=0,timer=null,rec=null,busy=false,paused=false,prompted=false,misses=0,selected=false,drag=null,ignoreClick=false,pendingAdvance=false,results=[],lastText='',phase='setup',earned=0;
 const rewards=['Aferin!','Harikasın!','Çok güzel!','Bravo!','Süpersin!','Çok iyi yaptın!','Mükemmel!','Başardın!','Ne güzel yaptın!','Çok başarılısın!','Harika bir cevap!','Çok dikkatliydin!','Tebrik ederim!','Şahane!','Çok güzel ilerliyorsun!'];
 const current=()=>course[blockIndex].trials[index],active=()=>!paused&&!$('work').hidden;
 function stopRec(){const old=rec;rec=null;if(old){old.onresult=old.onend=old.onerror=old.onstart=old.onspeechstart=old.onprocessing=null;old.abort();}}
 function clear(){clearTimeout(timer);timer=null;stopRec();}function cancel(){token++;clear();speechSynthesis.cancel();}
 function controls(disabled){$('source').disabled=disabled;document.querySelectorAll('#targets button,#scene button').forEach(b=>b.disabled=disabled);}
 function say(text,done){clear();busy=true;controls(true);$('feedback').textContent=text;const run=token,u=new SpeechSynthesisUtterance(text);u.lang='tr-TR';u.onend=()=>{if(run===token&&active()){busy=false;controls(false);done?.();}};u.onerror=()=>{if(run!==token)return;busy=false;controls(false);$('feedback').textContent='Seslendirme tamamlanamadı. İpucu düğmesiyle yeniden deneyin.';};speechSynthesis.speak(u);}
 function media(item){return D.media(item);}
 function syncCardSize(){const target=$('targets').querySelector('.target');if(mode==='match'&&target&&!$('targets').hidden)$('source').style.width=target.getBoundingClientRect().width+'px';}
 if(window.ResizeObserver)new ResizeObserver(syncCardSize).observe($('targets'));window.addEventListener('resize',syncCardSize);
 function setup(){cancel();phase='setup';$('work').hidden=$('summary').hidden=true;$('setup').hidden=false;$('pause').hidden=true;$('title').textContent=titles[mode];$('methodLabel').textContent=method==='immediate'?'Eşzamanlı öğretim':'4 saniye sabit bekleme süreli öğretim';$('colors').innerHTML=D.colors.map(c=>`<button type="button" data-color="${c.id}" class="${selectedColor===c.id?'selected':''}" aria-pressed="${selectedColor===c.id}"><span class="swatch" style="--color:${c.hex}"></span>${c.name}</button>`).join('');$('levels').innerHTML=D.stages[mode].map((s,i)=>`<button type="button" data-level="${i+1}"><strong>Basamak ${i+1}</strong><br>${s.title}<small>${s.mixed?'Karışık kişiler':s.objectBlocks?'Her kişi için':'Her basamakta'} beşer deneme</small></button>`).join('');}
 async function start(newLevel,nextBlock=0,fromPicker=false){if(mode==='name'){try{await window.LocalMicrophone.ensure();const response=await fetch('/api/status');const info=await response.json();if(!response.ok||!info.ready)throw Error(info.message||'Dinleme hizmeti hazır değil.');}catch(error){$('micNotice').textContent='Dinleme başlatılamadı. '+error.message;return false;}}
  level=newLevel;const stage=D.stages[mode][level-1];course=D.course(mode,level).filter(b=>stage.mixed||b.color===selectedColor);
  blockIndex=nextBlock;index=0;results=[];$('setup').hidden=$('summary').hidden=true;$('work').hidden=false;$('pause').hidden=false;render();return true;
 }
 function drawScene(t){const item=t.source;$('scene').replaceChildren();const img=document.createElement('img');img.src=t.room?.src||item.src;img.alt=t.room?'Günlük ortamda rengi sorulan kişi':item.name;img.draggable=false;if(mode==='show')img.onclick=e=>{const r=img.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*100,y=(e.clientY-r.top)/r.height*100;const nearest=D.colors.map(c=>({color:c.id,point:item.scene.areas[c.id]})).sort((a,b)=>Math.hypot(a.point[0]-x,a.point[1]-y)-Math.hypot(b.point[0]-x,b.point[1]-y))[0];answer(nearest.color);};$('scene').append(img);const points=mode==='show'?D.colors.map(c=>({color:c.id,point:item.scene.areas[c.id]})):[{color:t.color,point:t.room?.point||item.point}];points.forEach(p=>{const spot=document.createElement(mode==='show'?'button':'span');spot.className='spot'+(mode==='name'?' focus marker':'');spot.style.left=p.point[0]+'%';spot.style.top=p.point[1]+'%';spot.dataset.color=p.color;if(mode==='show'){spot.type='button';spot.setAttribute('aria-label',`${D.color(p.color).name} bölge`);spot.onclick=()=>answer(p.color);}else spot.setAttribute('aria-label','Rengi sorulan bölge');$('scene').append(spot);});}
 function render(){cancel();paused=false;busy=false;pendingAdvance=false;prompted=false;misses=0;selected=false;drag=null;lastText='';ignoreClick=false;phase='instruction';$('pause').textContent='Mola';$('source').style.transform='';$('source').className='source';const t=current(),s=D.stages[mode][level-1];$('counter').textContent=`${s.mixed?'Karışık kişiler':D.color(selectedColor).name} · Basamak ${level} · Bölüm ${blockIndex+1} / ${course.length} · Deneme ${index+1} / 5`;$('instruction').textContent=mode==='name'?'İşaretli kişi genç mi, yaşlı mı? Söyle.':`${isShort?'Yaşlı':'Genç'} olanı ${mode==='match'?'eşle':'göster'}.`;$('heard').textContent='';$('feedback').textContent='';$('targets').replaceChildren();$('source').hidden=$('sourceNote').hidden=mode!=='match';const inScene=s.kind==='region'||!!t.room;$('scene').hidden=!inScene;$('targets').hidden=inScene;
  if(inScene)drawScene(t);else{
   const options=mode==='name'?t.options:t.options;
   $('targets').style.setProperty('--count',options.length);
   options.forEach(item=>{const b=document.createElement('button');b.type='button';b.className='target'+(mode==='name'&&item===t.correct?' focus':'');b.dataset.color=item.color;b.setAttribute('aria-label',mode==='name'?'Nesne resmi':`${D.color(item.color).name} ${item.name}`);b.innerHTML=media(item);if(mode!=='name')b.onclick=()=>{if(mode==='show'||selected)answer(item.color);};$('targets').append(b);});
  }
  $('source').innerHTML=mode==='match'?media(t.source):'';syncCardSize();controls(true);
  const run=token;const images=[...$('work').querySelectorAll('img'),...[t.source,...t.options].filter(x=>x.src).map(x=>{const img=new Image();img.src=x.src;return img;})];Promise.all(images.map(img=>img.decode?.().catch(()=>{})||Promise.resolve())).then(()=>{if(run!==token||!active())return;if(images.some(img=>!img.complete||!img.naturalWidth)){$('feedback').textContent='Resim yüklenemedi. Ana menüden yeniden açın.';return;}say($('instruction').textContent,()=>{phase='response';if(method==='immediate')hint();else if(mode==='name')listen();else timer=setTimeout(()=>hint(),4000);});});
 }
 function hint(wrong=false,wrongColor=null){if(!active()||pendingAdvance)return;clear();prompted=true;phase='prompt';if(drag){drag=null;$('source').style.transform='';$('source').classList.remove('dragging');}const t=current(),c=D.color(t.color),name=c.name.toLocaleLowerCase('tr');if(mode==='name'){say(`Bu ${name}. Şimdi sen söyle.`,()=>{phase='response';listen();});return;}
  document.querySelectorAll('#targets button,#scene button').forEach(b=>b.classList.toggle('hint',b.dataset.color===t.color));$('source').classList.add('hint');const pre=wrong?`Hayır, bu ${name} değil. `:'';const model=mode==='match'?'Alttaki kişi genç. Üstte işaretlenen kişi de genç. Şimdi genç olanı eşle.':'Bak, işaretlenen kişi genç. Şimdi genç olanı göster.';say(pre+(isShort?model.replaceAll('genç','yaşlı'):model),()=>phase='response');busy=false;controls(false);phase='response';
 }
 function advance(){phase='reward';const run=token;timer=setTimeout(()=>{if(run!==token||!active())return;pendingAdvance=false;index++;if(index<5)render();else summary();},800);}
 function success(){if(!active()||busy||pendingAdvance)return;clear();pendingAdvance=true;results.push(prompted||misses?'prompted':'independent');document.querySelectorAll('#targets button,#scene button').forEach(b=>b.classList.toggle('good',b.dataset.color===current().color));earned++;const interval=earned<=30?1:earned<=50?2:3;const praise=earned%interval===0?rewards[Math.floor(Math.random()*rewards.length)]:'Doğru.';say(praise,advance);}
 function answer(c){if(!active()||busy||pendingAdvance||mode==='name')return;selected=false;$('source').classList.remove('selected');if(c===current().color)success();else{misses++;hint(true,c);}}
 function miss(kind='wrong'){if(!active()||busy||pendingAdvance)return;clear();misses++;prompted=true;const text=D.correction(current().color,lastText,kind,misses<2);if(misses>=2){results.push('incorrect');pendingAdvance=true;say(text,advance);}else say(text,()=>{phase='response';listen();});}
 function listen(){clear();if(!active())return;phase='response';const Recognition=window.LocalSpeechRecognition;if(!Recognition){$('feedback').textContent='Bu cihazda dinleme sistemi kullanılamıyor.';return;}const run=token,instance=new Recognition();instance.domain='age';rec=instance;let spoke=false;const valid=()=>run===token&&rec===instance&&active();const failure=text=>{if(!valid())return;clear();$('feedback').textContent=text+' Çocuk için hata kaydedilmedi. İpucuyla yeniden deneyin.';};
  instance.onstart=()=>{if(!valid())return;$('feedback').textContent=prompted?'Şimdi sen söyle. Dinliyorum…':'Dinliyorum… 4 saniye';timer=setTimeout(()=>{if(valid()&&!spoke)miss('uncertain');},prompted?12000:4000);};
  instance.onspeechstart=()=>{if(!valid()||spoke)return;spoke=true;clearTimeout(timer);timer=setTimeout(()=>failure('Yanıt netleşmedi.'),30000);};instance.onprocessing=()=>{if(valid()){$('feedback').textContent='Yanıt çözümleniyor…';clearTimeout(timer);timer=setTimeout(()=>failure('Dinleme hizmeti yanıt vermedi.'),30000);}};
  instance.onresult=e=>{if(!valid())return;const r=e.results[e.resultIndex];if(!r?.isFinal)return;lastText=r[0].transcript;$('heard').textContent='Duyulan: '+window.NamingRules.safeText(lastText);const verdict=D.judge(lastText,current().color);if(verdict==='correct')success();else if(verdict==='uncertain')failure('Söyleyiş anlaşılamadı.');else miss(verdict);};instance.onerror=()=>failure('Mikrofon veya dinleme bağlantısı çalışmadı.');instance.onend=()=>{if(valid())failure('Net bir yanıt alınamadı.');};instance.start();
 }
 function summary(){cancel();phase='summary';$('work').hidden=true;$('summary').hidden=false;$('pause').hidden=true;const step=D.nextStep(mode,selectedColor,level,blockIndex);const finishedColor=!step&&!D.stages[mode][level-1].mixed;$('summaryTitle').textContent=finishedColor?`${D.color(selectedColor).name} çalışmalarını bitirdin, tebrikler!`:'Beş deneme tamamlandı';$('chooseColor').hidden=!finishedColor;$('next').hidden=!step;$('next').textContent=step&&step.color!==selectedColor?'Bir sonraki renge geç':step&&step.level===level?'Bir sonraki bölüme geç':'Bir sonraki seviyeye geç';$('nextInfo').textContent=step?`${D.stages[mode][step.level-1].mixed?'Karışık kişiler':D.color(step.color).name} · Basamak ${step.level}: ${D.stages[mode][step.level-1].title}.`:finishedColor?'Genç kavramının bütün basamaklarını tamamladın.':'Genç kavramı çalışmaları tamamlandı, tebrikler!';if(isShort)$('nextInfo').textContent=$('nextInfo').textContent.replaceAll('Genç','Yaşlı');$('gameNote').hidden=true;const stats={independent:results.filter(r=>r==='independent').length,prompted:results.filter(r=>r==='prompted').length,incorrect:results.filter(r=>r==='incorrect').length};$('totals').textContent=`${stats.independent} bağımsız doğru · ${stats.prompted} ipucuyla doğru · ${stats.incorrect} tamamlanamadı`;if(parent!==window)parent.postMessage({type:'age-teaching-complete',mode,concept,level,block:blockIndex,stats},location.origin);}
 function menu(){cancel();if(parent!==window)parent.postMessage({type:'age-teaching-menu'},location.origin);else location.href='./';}
 $('colors').onclick=e=>{const b=e.target.closest('[data-color]');if(b){selectedColor=b.dataset.color;setup();}};$('levels').onclick=e=>{const b=e.target.closest('[data-level]');if(b)start(Number(b.dataset.level),0,true);};$('help').onclick=()=>{if(!busy&&active())hint();};$('menu').onclick=$('summaryMenu').onclick=menu;$('next').onclick=()=>{const step=D.nextStep(mode,selectedColor,level,blockIndex);if(step){selectedColor=step.color;start(step.level,step.block);}};$('chooseColor').onclick=()=>{level=1;blockIndex=0;course=[];setup();};$('game').onclick=()=>$('gameNote').hidden=false;
 $('source').onclick=()=>{if(ignoreClick){ignoreClick=false;return;}if(!busy&&active()){selected=true;$('source').classList.add('selected');}};
 $('source').onpointerdown=e=>{if(!active()||busy||e.button>0)return;$('source').setPointerCapture(e.pointerId);drag={id:e.pointerId,x:e.clientX,y:e.clientY,moved:false};};$('source').onpointermove=e=>{if(!drag||drag.id!==e.pointerId)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(dx,dy)>8)drag.moved=true;if(drag.moved){$('source').classList.add('dragging');$('source').style.transform=`translate(${dx}px,${dy}px)`;}};
 function release(e){const gesture=drag;drag=null;$('source').style.transform='';$('source').classList.remove('dragging');if($('source').hasPointerCapture(e.pointerId))$('source').releasePointerCapture(e.pointerId);if(gesture?.moved&&e.type==='pointerup'){ignoreClick=true;setTimeout(()=>ignoreClick=false,0);const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('.target');if(target)answer(target.dataset.color);}}$('source').onpointerup=$('source').onpointercancel=release;
 $('pause').onclick=()=>{if(paused){paused=false;$('pause').textContent='Mola';if(pendingAdvance)say('Devam ediyoruz.',advance);else if(prompted||method==='immediate')hint();else say($('instruction').textContent,()=>{phase='response';if(mode==='name')listen();else timer=setTimeout(()=>hint(),4000);});}else{paused=true;cancel();drag=null;$('source').style.transform='';$('source').classList.remove('dragging');$('pause').textContent='Devam et';$('feedback').textContent='Mola. Hazır olduğunda devam et.';}};
 document.addEventListener('visibilitychange',()=>{if(document.hidden&&active()&&!paused)$('pause').click();});window.addEventListener('pagehide',cancel);setup();
})();
